import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«מפת השפעה» и приглашение', () => {
  test('IM-03 Своя ссылка приглашения у вошедшего → «זה קישור ההזמנה שלך…» #6a86f7e6 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: чистое pending-invite (если ключа нет или он уже в чистом состоянии).
    await page.addInitScript(() => {
      const clean = JSON.stringify({ state: { inviter: null, owner: null, joined: null }, version: 0 });
      const cur = localStorage.getItem('pending-invite');
      if (cur === null || cur === clean) localStorage.setItem('pending-invite', clean);
    });

    // 2. Открыть `/?invite=c750744f-6d79-4dd5-a891-0b3446eb08cd`.
    await page.goto('/?invite=c750744f-6d79-4dd5-a891-0b3446eb08cd');
    await expect(page.getByText('זה קישור ההזמנה שלך. אפשר לשלוח אותו למי שרוצה להתחזק איתך.')).toBeVisible({ timeout: 20_000 });

    // 3. Открыть `/journey`.
    await page.goto('/journey');
    await expect(page.getByRole('heading', { name: 'מפת השפעה' })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await expect(page.getByText('2 אנשים', { exact: true })).toBeVisible();

    // Уборка локального состояния браузера: вернуть чистое pending-invite.
    await page.evaluate(() =>
      localStorage.setItem('pending-invite', JSON.stringify({ state: { inviter: null, owner: null, joined: null }, version: 0 })),
    );
  });
});
